#[derive(Debug, Clone, PartialEq, Eq)]
pub enum LookupError {
    EmptyKey,
    MalformedEntry { index: usize },
    ConflictingValues,
}

fn trim_ascii(value: &str) -> &str {
    value.trim_matches(|c: char| c.is_ascii_whitespace())
}

pub fn lookup_setting(
    entries: &[(String, String)],
    key: &str,
) -> Result<Option<String>, LookupError> {
    let key = trim_ascii(key);
    if key.is_empty() {
        return Err(LookupError::EmptyKey);
    }

    let mut found: Option<String> = None;
    for (index, (entry_key, entry_value)) in entries.iter().enumerate() {
        let entry_key = trim_ascii(entry_key);
        if entry_key.is_empty() || entry_key.chars().any(|c| c.is_ascii_control()) {
            return Err(LookupError::MalformedEntry { index });
        }
        if entry_key == key {
            let value = trim_ascii(entry_value);
            match &found {
                Some(previous) if previous != value => {
                    return Err(LookupError::ConflictingValues);
                }
                None => found = Some(value.to_owned()),
                _ => {}
            }
        }
    }
    Ok(found)
}

