#[path = "solution.rs"]
mod solution;

use solution::*;

fn entries(values: &[(&str, &str)]) -> Vec<(String, String)> {
    values
        .iter()
        .map(|(key, value)| ((*key).to_owned(), (*value).to_owned()))
        .collect()
}

#[test]
fn rejects_an_ascii_whitespace_only_lookup_key() {
    assert_eq!(lookup_setting(&[], " \t\r\n"), Err(LookupError::EmptyKey));
}

#[test]
fn returns_none_when_no_trimmed_case_insensitive_key_matches() {
    let data = entries(&[("host", "example"), ("port", "8080")]);
    assert_eq!(lookup_setting(&data, " mode "), Ok(None));
}

#[test]
fn trims_key_and_matched_value_and_compares_ascii_case_insensitively() {
    let data = entries(&[("  TiMeOuT  ", " \t30 seconds\r\n")]);
    assert_eq!(
        lookup_setting(&data, "\n timeout \t"),
        Ok(Some("30 seconds".to_owned()))
    );
}

#[test]
fn permits_repeated_matches_with_identical_trimmed_values() {
    let data = entries(&[
        (" Color ", " blue "),
        ("COLOR", "blue"),
        ("color", "\tblue\n"),
    ]);
    assert_eq!(lookup_setting(&data, "color"), Ok(Some("blue".to_owned())));
}

#[test]
fn permits_empty_matched_values_when_consistent() {
    let data = entries(&[("key", "  "), (" KEY ", "\n")]);
    assert_eq!(lookup_setting(&data, "key"), Ok(Some(String::new())));
}

#[test]
fn reports_conflicting_trimmed_values() {
    let data = entries(&[("key", "same"), ("other", "ignored"), ("KEY", " different ")]);
    assert_eq!(lookup_setting(&data, "key"), Err(LookupError::ConflictingValues));
}

#[test]
fn validates_unmatched_entries_and_reports_first_malformed_index() {
    let data = entries(&[
        ("target", "found"),
        ("valid", "value"),
        ("   ", "bad"),
        ("", "also bad"),
    ]);
    assert_eq!(
        lookup_setting(&data, "target"),
        Err(LookupError::MalformedEntry { index: 2 })
    );
}

#[test]
fn an_ascii_control_character_makes_an_entry_key_malformed() {
    let data = entries(&[("normal", "v"), ("bad\u{7f}key", "x")]);
    assert_eq!(
        lookup_setting(&data, "absent"),
        Err(LookupError::MalformedEntry { index: 1 })
    );

    let tabbed = entries(&[("tab\tkey", "v")]);
    assert_eq!(
        lookup_setting(&tabbed, "tab key"),
        Err(LookupError::MalformedEntry { index: 0 })
    );
}

#[test]
fn matching_is_ascii_only() {
    let data = entries(&[("ÉCOLE", "upper"), ("école", "lower")]);
    assert_eq!(lookup_setting(&data, "école"), Ok(Some("lower".to_owned())));
}

#[test]
fn inputs_are_not_mutated_and_output_is_owned() {
    let data = entries(&[(" Key ", " value ")]);
    let before = data.clone();
    let key = String::from(" key ");
    let key_before = key.clone();

    let mut output = lookup_setting(&data, &key).unwrap().unwrap();
    output.push('!');

    assert_eq!(data, before);
    assert_eq!(key, key_before);
    assert_eq!(data[0].1, " value ");
}

